<script setup>
import { onBeforeUnmount, reactive, ref, watch } from "vue";
import { addAssignment, addComment, addShare, emailDocument, getCollaborationState, removeAssignment, removeAttachment, removeShare, searchAssignmentUsers, setTags, uploadAttachment } from "@/services/universal.js";
const props = defineProps({ feature: { type: String, required: true }, name: { type: String, required: true }, printOptions: { type: Object, default: () => ({}) } });
const state = ref(null); const loading = ref(true); const error = ref(""); const busy = ref(false); const comment = ref(""); const tagText = ref(""); const assignment = reactive({ user: "", dueDate: "", description: "" }); const userOptions = ref([]); const share = reactive({ user: "", write: false }); const email = reactive({ recipients: "", subject: "", message: "", attachPdf: false, printFormat: "Standard" }); let controller; let userTimer;
async function load() { controller?.abort(); controller = new AbortController(); loading.value = true; error.value = ""; try { state.value = await getCollaborationState(props.feature, props.name, controller.signal); tagText.value = (state.value.tags || []).join(", "); email.subject ||= props.name; } catch (caught) { if (caught.name !== "AbortError") error.value = caught.message; } finally { loading.value = false; } }
async function perform(action) { if (busy.value) return; busy.value = true; error.value = ""; try { await action(); await load(); } catch (caught) { error.value = caught.message; } finally { busy.value = false; } }
function searchUsers() { window.clearTimeout(userTimer); userTimer = window.setTimeout(async () => { try { userOptions.value = (await searchAssignmentUsers(props.feature, props.name, assignment.user, undefined)).results; } catch { userOptions.value = []; } }, 250); }
function upload(event) { const file = event.target.files?.[0]; if (file) perform(() => uploadAttachment(state.value.upload, file)); event.target.value = ""; }
function sendEmail() { const recipients = email.recipients.split(/[;,]/).map((value) => value.trim()).filter(Boolean); perform(() => emailDocument(props.feature, props.name, { recipients, subject: email.subject, message: email.message, attach_pdf: Number(email.attachPdf), print_format: email.printFormat })); }
watch(() => [props.feature, props.name], load, { immediate: true }); onBeforeUnmount(() => { controller?.abort(); window.clearTimeout(userTimer); });
</script>
<template><section class="rug-collaboration"><header><div><h2>Collaboration</h2><p>Attachments, comments, assignments, sharing and history.</p></div><button type="button" :disabled="loading" @click="load">Refresh</button></header><div v-if="error" class="rug-inline-error" role="alert">{{ error }}</div><div v-if="loading && !state" class="rug-skeleton"><i v-for="n in 4" :key="n" /></div><template v-else-if="state">
  <div class="rug-collab-grid"><article><h3>Attachments</h3><label v-if="state.permissions.can_attach" class="rug-upload"><input type="file" @change="upload" />Upload private file</label><div v-if="!state.attachments.length" class="rug-muted">No attachments.</div><div v-for="file in state.attachments" :key="file.name" class="rug-row"><a :href="file.download_url" target="_blank" rel="noopener">{{ file.file_name }}</a><button v-if="state.permissions.can_remove_attachment" type="button" @click="perform(() => removeAttachment(feature, name, file.name))">Remove</button></div></article>
  <article><h3>Comments</h3><form v-if="state.permissions.can_comment" @submit.prevent="perform(async () => { await addComment(feature,name,comment); comment=''; })"><textarea v-model="comment" rows="3" required placeholder="Add a comment…" /><button class="rug-primary" type="submit" :disabled="busy">Comment</button></form><div v-if="!state.comments.length" class="rug-muted">No comments.</div><div v-for="row in state.comments" :key="row.name" class="rug-comment"><p>{{ row.content }}</p><small>{{ row.owner }} · {{ row.creation }}</small></div></article>
  <article><h3>Assignments</h3><form v-if="state.permissions.can_assign" @submit.prevent="perform(async () => { await addAssignment(feature,name,assignment.user,assignment.dueDate,assignment.description); assignment.user=''; })"><input v-model="assignment.user" list="rug-users" required placeholder="User" @input="searchUsers" /><datalist id="rug-users"><option v-for="user in userOptions" :key="user.value" :value="user.value">{{ user.label }}</option></datalist><input v-model="assignment.dueDate" type="date" /><input v-model="assignment.description" placeholder="Description" /><button type="submit" :disabled="busy">Assign</button></form><div v-if="!state.assignments.length" class="rug-muted">No active assignments.</div><div v-for="row in state.assignments" :key="row.name" class="rug-row"><span>{{ row.owner }}</span><button v-if="state.permissions.can_assign" type="button" @click="perform(() => removeAssignment(feature,name,row.owner))">Unassign</button></div></article>
  <article><h3>Tags and sharing</h3><form v-if="state.permissions.can_tag" @submit.prevent="perform(() => setTags(feature,name,tagText.split(',').map((value) => value.trim()).filter(Boolean)))"><input v-model="tagText" placeholder="Comma-separated tags" /><button type="submit">Save tags</button></form><form v-if="state.permissions.can_share" @submit.prevent="perform(async () => { await addShare(feature,name,share.user,{write:Number(share.write)}); share.user=''; })"><input v-model="share.user" type="email" required placeholder="Share with user" /><label><input v-model="share.write" type="checkbox" /> Allow editing</label><button type="submit">Share</button></form><div v-for="row in state.shares" :key="row.name" class="rug-row"><span>{{ row.user }} · {{ row.write ? 'Read/write' : 'Read' }}</span><button type="button" @click="perform(() => removeShare(feature,name,row.user))">Remove</button></div></article>
  </div>
  <details v-if="state.permissions.can_email" class="rug-email"><summary>Email this document</summary><div class="rug-dialog-grid"><label><span>Recipients</span><input v-model="email.recipients" placeholder="name@example.com" /></label><label><span>Subject</span><input v-model="email.subject" /></label><label class="is-wide"><span>Message</span><textarea v-model="email.message" rows="4" /></label><label><span>Print format</span><select v-model="email.printFormat"><option v-for="format in printOptions.formats || ['Standard']" :key="format">{{ format }}</option></select></label><label><input v-model="email.attachPdf" type="checkbox" :disabled="!printOptions.pdf_environment?.available" /> Attach PDF</label></div><button class="rug-primary" type="button" :disabled="busy" @click="sendEmail">Send email</button></details>
  <details class="rug-versions"><summary>Version history ({{ state.versions.length }})</summary><div v-if="!state.versions.length" class="rug-muted">Version tracking is not enabled or no changes are recorded.</div><div v-for="version in state.versions" :key="version.name" class="rug-row"><span>{{ version.creation }} · {{ version.owner }}</span><small>{{ version.changed_fields.join(', ') || 'Document change' }}</small></div></details>
</template></section></template>
